mapper.select:
SELECT COUNT(1)
FROM biz_device_mgmt.device_metrics_shift dms
INNER JOIN biz_device_base.device_base_info dbi ON dms.device_id = dbi.id
WHERE dms.tenant_id = #{tenantId}
  AND dbi.factory_id = #{factoryId}
  AND dms.shift_date = #{shiftDate}::date
  AND dms.shift_code = #{shiftCode}
  AND dms.metrics ? #{metricCode}  -- 检查JSONB中是否存在该指标

      AND dbi.workshop_id = #{workshopId}
